    @SubscribeEvent public static void install(LevelEvent.Load event){if(!GameTestHooks.isGametestEnabled()||!(event.getLevel() instanceof ServerLevel level))return;var tag=new CompoundTag();var size=new ListTag();for(int n:new int[]{40,64,40})size.add(IntTag.valueOf(n));tag.put("size",size);var blocks=new ListTag();var air=new CompoundTag();var pos=new ListTag();for(int n=0;n<3;n++)pos.add(IntTag.valueOf(0));air.put("pos",pos);air.putInt("state",0);blocks.add(air);tag.put("blocks",blocks);tag.put("entities",new ListTag());var palette=new ListTag();var entry=new CompoundTag();entry.putString("Name","minecraft:air");palette.add(entry);tag.put("palette",palette);level.getStructureManager().getOrCreate(ResourceLocation.fromNamespaceAndPath("academy",TEMPLATE)).load(level.registryAccess().lookupOrThrow(Registries.BLOCK),tag);}
    private static void equal(GameTestHelper h,double expected,double actual,String label){h.assertTrue(Double.isFinite(actual)&&Math.abs(expected-actual)<1e-7,label+": "+actual);}
    private static ItemStack s(Item item){return new ItemStack(item);}
    private static void near(ServerPlayer player,BlockPos pos){player.moveTo(pos.getX()+.5,pos.getY(),pos.getZ()-2.5,0,0);}
    private static BlockPlaceContext context(ServerPlayer player,BlockPos pos,ItemStack item){player.setItemInHand(InteractionHand.MAIN_HAND,item);return new BlockPlaceContext(player,InteractionHand.MAIN_HAND,item,new BlockHitResult(Vec3.atCenterOf(pos),Direction.UP,pos,false));}
    /** Direct state fixtures are declared empty native components, with every sibling's real PART/FACING. */
    private static void component(GameTestHelper h,BlockPos relative,ClassicWindBlock block,Direction facing){var state=block.defaultBlockState().setValue(ClassicWindBlock.FACING,facing);var origin=h.absolutePos(relative);for(int part=0;part<ClassicWindRules.parts(block.kind);part++){var pos=origin.offset(ClassicWindBlock.offset(state,part));h.assertTrue(h.getLevel().isEmptyBlock(pos),"declared component refuses occupied cells");h.getLevel().setBlock(pos,state.setValue(ClassicWindBlock.PART,part),Block.UPDATE_CLIENTS|Block.UPDATE_KNOWN_SHAPE);}}
    private record Tower(ClassicWindBaseBlockEntity base,ClassicWindMainBlockEntity main){}
    private static Tower tower(GameTestHelper h,int pillars,Direction facing,boolean fan){component(h,BASE,ClassicWindGenerators.BASE.get(),facing);for(int i=0;i<pillars;i++)component(h,BASE.above(i+2),ClassicWindGenerators.PILLAR.get(),Direction.NORTH);component(h,BASE.above(pillars+2),ClassicWindGenerators.MAIN.get(),facing);var base=(ClassicWindBaseBlockEntity)h.getBlockEntity(BASE);var main=(ClassicWindMainBlockEntity)h.getBlockEntity(BASE.above(pillars+2));if(fan)main.setItem(0,s(ClassicWindGenerators.FAN.get()));return new Tower(base,main);}
    private static void mainTicks(GameTestHelper h,ClassicWindMainBlockEntity main,int count){for(int i=0;i<count;i++)ClassicWindMainBlockEntity.serverTick(h.getLevel(),main.getBlockPos(),main.getBlockState(),main);}
    private static void baseTicks(GameTestHelper h,ClassicWindBaseBlockEntity base,int count){for(int i=0;i<count;i++)ClassicWindBaseBlockEntity.serverTick(h.getLevel(),base.getBlockPos(),base.getBlockState(),base);}
    private static void warm(GameTestHelper h,Tower tower){mainTicks(h,tower.main,10);baseTicks(h,tower.base,10);}
    private static ClassicWirelessProtocol.Request request(ClassicWirelessMenu menu,String action,BlockPos target,String password){return new ClassicWirelessProtocol.Request(menu.containerId,menu.token(),action,target,"",password);}
    @GameTest(template=TEMPLATE,batch=BATCH,timeoutTicks=20)
    public static void wind_native_registry_source_flat_items_fan_harvest_and_all_yaw_placements(GameTestHelper h){try(var actors=new AcademyWirelessDeviceRuntimeTests.NativeMenuActors(h)){var player=actors.player();for(int facing=0;facing<4;facing++){BlockPos relative=BASE.offset((facing-2)*3,0,0),pos=h.absolutePos(relative);near(player,pos);player.setYRot(facing*90);var stack=s(ClassicWindGenerators.MAIN_ITEM.get());h.assertTrue(ClassicWindGenerators.MAIN_ITEM.get().place(context(player,pos,stack)).consumesAction()&&stack.isEmpty(),"actual source main item consumes once");var state=h.getLevel().getBlockState(pos);h.assertTrue(state.getValue(ClassicWindBlock.FACING).name().equals(ClassicWindRules.fromYaw(facing*90).name()),"source yaw-map orientation");for(int part=0;part<3;part++){var cell=pos.offset(ClassicWindBlock.offset(state,part));var sibling=h.getLevel().getBlockState(cell);h.assertTrue(sibling.is(ClassicWindGenerators.MAIN.get())&&sibling.getValue(ClassicWindBlock.PART)==part&&sibling.getValue(ClassicWindBlock.FACING)==state.getValue(ClassicWindBlock.FACING),"three actual source occupied cells");h.assertTrue(sibling.getCollisionShape(h.getLevel(),cell).equals(net.minecraft.world.phys.shapes.Shapes.block()),"source fullcell collision");}h.getLevel().removeBlock(pos,false);}
        var fan=s(ClassicWindGenerators.FAN.get());h.assertValueEqual(fan.getMaxDamage(),100,"source fan unused100 durability");h.assertValueEqual(fan.getMaxStackSize(),1,"source fan stack1");for(var block:new ClassicWindBlock[]{ClassicWindGenerators.BASE.get(),ClassicWindGenerators.PILLAR.get(),ClassicWindGenerators.MAIN.get()}){h.assertTrue(BuiltInRegistries.BLOCK.getKey(block).getNamespace().equals("academy"),"genuine block registry");h.assertTrue(block.defaultBlockState().is(net.minecraft.tags.BlockTags.MINEABLE_WITH_PICKAXE)&&block.defaultBlockState().is(net.minecraft.tags.BlockTags.NEEDS_IRON_TOOL),"source hardness4 pickaxelevel2");}h.succeed();}}
