    public static void wind_native_atomic_blocked_auxiliary_placement_never_consumes_or_overwrites(GameTestHelper h){try(var actors=new AcademyWirelessDeviceRuntimeTests.NativeMenuActors(h)){var player=actors.player();var pos=h.absolutePos(BASE);near(player,pos);player.setYRot(0);h.getLevel().setBlockAndUpdate(pos.north(),Blocks.STONE.defaultBlockState());var stack=s(ClassicWindGenerators.MAIN_ITEM.get());h.assertFalse(ClassicWindGenerators.MAIN_ITEM.get().place(context(player,pos,stack)).consumesAction(),"blocked original main sibling refuses wholeplacement");h.assertValueEqual(stack.getCount(),1,"blocked placement consumes0");h.assertTrue(h.getLevel().isEmptyBlock(pos)&&h.getLevel().getBlockState(pos.north()).is(Blocks.STONE)&&h.getLevel().isEmptyBlock(pos.south()),"no partial native footprint/no foreign replacement");var base=s(ClassicWindGenerators.BASE_ITEM.get());h.getLevel().setBlockAndUpdate(pos.above(),Blocks.DIAMOND_BLOCK.defaultBlockState());h.assertFalse(ClassicWindGenerators.BASE_ITEM.get().place(context(player,pos,base)).consumesAction(),"blocked upper base refuses");h.assertValueEqual(base.getCount(),1,"base transaction consumes0");h.assertTrue(h.getLevel().isEmptyBlock(pos)&&h.getLevel().getBlockState(pos.above()).is(Blocks.DIAMOND_BLOCK),"base blocked foreign state unchanged");h.getLevel().removeBlock(pos.above(),false);h.assertTrue(ClassicWindGenerators.BASE_ITEM.get().place(context(player,pos,base)).consumesAction(),"real two-cell base placed after obstruction clears");var pillar=s(ClassicWindGenerators.PILLAR_ITEM.get());player.setItemInHand(InteractionHand.MAIN_HAND,pillar);var upper=pos.above();h.assertTrue(player.gameMode.useItemOn(player,h.getLevel(),pillar,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(upper),Direction.UP,upper,false)).consumesAction(),"real modern item-on-block route preserves original held-pillar bypass");h.assertTrue(h.getLevel().getBlockState(pos.above(2)).is(ClassicWindGenerators.PILLAR.get())&&pillar.isEmpty(),"actual pillar placed above upperbase");h.assertFalse(player.containerMenu instanceof ClassicWindMenu,"pillar use does not unexpectedly open baseGUI");h.succeed();}}
    @GameTest(template=TEMPLATE,batch=BATCH,timeoutTicks=20)
    public static void wind_native_minimum_tower_generation_refresh_battery_and_obstacle_source_quirk(GameTestHelper h){var tower=tower(h,8,Direction.NORTH,true);warm(h,tower);equal(h,0,tower.base.getEnergy(),"source generation waits prior10tick tower refresh");h.assertTrue(tower.main.complete()&&tower.main.noObstacle()&&tower.base.isComplete(),"source minimum8 fulltower");double rate=ClassicWindRules.generation(tower.main.getBlockPos().getY(),true);var battery=s(ClassicEnergyItems.ENERGY_UNIT.get());tower.base.setItem(0,battery);baseTicks(h,tower.base,1);equal(h,rate,ClassicEnergyItemHelper.getEnergy(battery),"genuine IF item charged from actual windgeneration");equal(h,0,tower.base.getEnergy(),"generation/item total conserved");var plane=tower.main.getBlockPos().offset(1,0,-1);h.getLevel().setBlockAndUpdate(plane,Blocks.STONE.defaultBlockState());mainTicks(h,tower.main,10);h.assertFalse(tower.main.noObstacle(),"source native obstacle hides rotor");equal(h,rate,tower.base.simulatedGeneration(),"literal obstacle does not stop source IF");tower.main.setItem(0,ItemStack.EMPTY);equal(h,0,tower.base.simulatedGeneration(),"fan removal stops sourcegeneration");h.assertTrue(tower.base.completeness()==ClassicWindRules.Completeness.COMPLETE_NOT_WORKING,"source GUI nofan alpha status");h.succeed();}
